// 1. Create a file `test.html` next to this script:
//
// <!DOCTYPE html>
// <html lang="en">
// <head>
//   <meta charset="utf-8">
//   <title>Local Resource Bug</title>
//   <!-- This file:// URL will never load, but Lighthouse still flags it -->
//   <link rel="stylesheet" href="file:///some/local/style.css">
//   <script src="file:///some/local/script.js"></script>
// </head>
// <body>
//   <h1>Testing local (file://) resources in Lighthouse</h1>
// </body>
// </html>

const http = require('http');
const fs = require('fs');
const path = require('path');
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

(async () => {
  // 2. Start a simple HTTP server to serve test.html
  const html = fs.readFileSync(path.join(__dirname, 'test.html'), 'utf8');
  const server = http.createServer((req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(html);
  });
  await new Promise(resolve => server.listen(8080, resolve));
  console.log('Server running at http://localhost:8080');

  // 3. Launch Chrome and run Lighthouse
  const chrome = await chromeLauncher.launch({ chromeFlags: ['--headless'] });
  const options = {
    port: chrome.port,
    output: 'json',
    logLevel: 'info',
    onlyCategories: ['performance'],
  };

  const runnerResult = await lighthouse('http://localhost:8080', options);
  const lhr = runnerResult.lhr;
  console.log('--- Render Blocking Resources Audit ---');
  console.log(JSON.stringify(
    lhr.audits['render-blocking-resources'].details.items,
    null,
    2
  ));

  // 4. Clean up
  await chrome.kill();
  server.close();
})();
